package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.NullifyingDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class TypeDeserializerBase__deserializeWithNativeTypeId_TriageGen1Test {

    private TestableTypeDeserializerBase typeDeserializerBase;
    private JsonParser mockJsonParser;
    private DeserializationContext mockDeserializationContext;
    private JavaType mockJavaType;
    private JsonDeserializer<Object> mockDeserializer;

    // Concrete implementation to test the protected method
    private static class TestableTypeDeserializerBase extends TypeDeserializerBase {

        protected TestableTypeDeserializerBase(JavaType baseType, TypeIdResolver idRes, String typePropertyName, boolean typeIdVisible, Class<?> defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
        }

        // Expose protected method for testing
        public Object public_deserializeWithNativeTypeId(JsonParser jp, DeserializationContext ctxt, Object typeId) throws IOException {
            return _deserializeWithNativeTypeId(jp, ctxt, typeId);
        }

        // Mockable hooks
        protected JsonDeserializer<Object> _findDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            return _findDeserializerSpy(ctxt, typeId);
        }

        protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            return _findDefaultImplDeserializerSpy(ctxt);
        }

        // Spies for the internal protected methods
        protected JsonDeserializer<Object> _findDeserializerSpy(DeserializationContext ctxt, String typeId) throws IOException {
            return null;
        }

        protected JsonDeserializer<Object> _findDefaultImplDeserializerSpy(DeserializationContext ctxt) throws IOException {
            return null;
        }

        @Override public TypeDeserializer forProperty(com.fasterxml.jackson.databind.BeanProperty prop) { return null; }
        @Override public com.fasterxml.jackson.annotation.JsonTypeInfo.As getTypeInclusion() { return null; }
        @Override public String baseTypeName() { return null; }
    }

    @Before
    public void setUp() {
        mockJsonParser = mock(JsonParser.class);
        mockDeserializationContext = mock(DeserializationContext.class);
        mockJavaType = mock(JavaType.class);
        mockDeserializer = mock(JsonDeserializer.class);

        // Using a spy to override the internal _find methods
        typeDeserializerBase = spy(new TestableTypeDeserializerBase(mockJavaType, mock(com.fasterxml.jackson.databind.jsontype.TypeIdResolver.class), "type", true, null));
    }

    @Test
    public void testDeserializeWithNullTypeId_Success() throws IOException {
        Object expectedResult = new Object();

        doReturn(mockDeserializer).when(typeDeserializerBase)._findDefaultImplDeserializer(mockDeserializationContext);
        when(mockDeserializer.deserialize(mockJsonParser, mockDeserializationContext)).thenReturn(expectedResult);

        Object result = typeDeserializerBase.public_deserializeWithNativeTypeId(mockJsonParser, mockDeserializationContext, null);

        assertEquals(expectedResult, result);
        verify(typeDeserializerBase)._findDefaultImplDeserializer(mockDeserializationContext);
        verify(mockDeserializer).deserialize(mockJsonParser, mockDeserializationContext);
    }

    @Test(expected = RuntimeException.class)
    public void testDeserializeWithNullTypeId_ThrowsExceptionWhenNoDeserializerFound() throws IOException {
        doReturn(null).when(typeDeserializerBase)._findDefaultImplDeserializer(mockDeserializationContext);
        when(mockDeserializationContext.mappingException(any(String.class))).thenThrow(new RuntimeException("Mapping Exception"));

        typeDeserializerBase.public_deserializeWithNativeTypeId(mockJsonParser, mockDeserializationContext, null);
    }

    @Test
    public void testDeserializeWithStringTypeId_Success() throws IOException {
        String typeId = "com.example.MyClass";
        Object expectedResult = new Object();

        doReturn(mockDeserializer).when(typeDeserializerBase)._findDeserializer(mockDeserializationContext, typeId);
        when(mockDeserializer.deserialize(mockJsonParser, mockDeserializationContext)).thenReturn(expectedResult);

        Object result = typeDeserializerBase.public_deserializeWithNativeTypeId(mockJsonParser, mockDeserializationContext, typeId);

        assertEquals(expectedResult, result);
        verify(typeDeserializerBase)._findDeserializer(mockDeserializationContext, typeId);
    }

    @Test
    public void testDeserializeWithNonStringTypeId_Success() throws IOException {
        Integer typeIdInt = 123;
        String expectedTypeIdStr = "123";
        Object expectedResult = new Object();

        doReturn(mockDeserializer).when(typeDeserializerBase)._findDeserializer(mockDeserializationContext, expectedTypeIdStr);
        when(mockDeserializer.deserialize(mockJsonParser, mockDeserializationContext)).thenReturn(expectedResult);

        Object result = typeDeserializerBase.public_deserializeWithNativeTypeId(mockJsonParser, mockDeserializationContext, typeIdInt);

        assertEquals(expectedResult, result);
        verify(typeDeserializerBase)._findDeserializer(mockDeserializationContext, expectedTypeIdStr);
    }
}
